if (!el) return;
el.innerHTML = `
      <span>💾 ${d.sqlite_memories||0} memories</span>
      <span>🔮 ${d.vectors_sqlite||0} vectors</span>
      <span title="${d.engine||''}">${d.status==='active'?'✅':'⚠️'} ${d.engine||'FTS5'}</span>`;
